fun p =>
  have this := Fintype.mem_piFinset.mp hv p;
  Eq.mpr (id ge_iff_le._simp_1) (Eq.mp (Eq.trans Finset.mem_range._simp_1 Order.lt_add_one_iff._simp_1) this)

nodes.ga:
n d σ k : ℕ
hn : 2 ≤ n
hσ : 1 ≤ σ
a : Fin σ
this : NeZero n
X : Finset (Config n d (Fin σ)) := {s | cellsInState s a = k}
hXdef : X = {s | cellsInState s a = k}
hnum : numKActive n d σ a k = (Finset.filter IsShiftSymmetric X).card
H : AddSubgroup (Lat n d)
⊢ (X ∩ fixedByA (Fin σ) H).card = Nat.card { s // s ∈ fixedBy (Fin σ) H ∧ cellsInState s a = k }

